async(page)=>{
 const base='https://bboy-lan.github.io/AI/',account=await(await page.request.get('http://127.0.0.1:5173/.release/session-account.secret.json')).json(),checks=[],browser=page.context().browser(),check=(v,m)=>{if(!v)throw Error(m);checks.push(m)},cloud=/tcloudbasegateway\.com|tcb-api\.tencentcloudapi\.com/
 for(const mobile of [false,true]){const context=await browser.newContext({viewport:mobile?{width:390,height:844}:{width:1440,height:900},...(mobile?{isMobile:true,hasTouch:true,userAgent:'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36 MicroMessenger/8.0.50'}:{})});try{const p=await context.newPage();await p.goto(base);await p.getByRole('heading',{name:'注册网页账号',exact:true}).waitFor();await p.getByRole('button',{name:'已有账号，去登录',exact:true}).click();await p.getByRole('textbox',{name:'登录账号',exact:true}).fill(account.name);await p.getByLabel('登录密码',{exact:true}).fill(account.password);await p.getByRole('button',{name:'登录',exact:true}).click();await p.locator('.profile-heading').waitFor({timeout:30000});check(await p.getByRole('dialog',{name:'公告',exact:true}).count()===0,'真实旧账号登录不重填资料或重弹已读 '+mobile);await p.getByRole('button',{name:'我的',exact:true}).click();await p.locator('.profile-heading').waitFor();check((await p.locator('.profile-heading').innerText()).includes('持久登录验收同学'),'正式入口恢复云端身份 '+mobile);check(await p.evaluate(password=>!Object.values(localStorage).some(v=>v.includes(password)),account.password),'本地没有明文密码 '+mobile);await context.setOffline(true);await p.getByRole('button',{name:'找吃的',exact:true}).click();await p.getByRole('heading',{name:'同乡今天吃什么。',exact:true}).waitFor();await p.getByRole('button',{name:'我的',exact:true}).click();await p.locator('.profile-heading').waitFor();check(true,'已打开页面断网后仍可切换缓存主页面 '+mobile);await context.setOffline(false);const credentials=await p.evaluate(()=>localStorage.getItem('credentials_cloud-yunda-d5gxrar1s14b2ee0d'));check(!!credentials,'断网后仍保留登录凭证 '+mobile);const block=r=>r.abort();await p.route(cloud,block);await p.reload();await p.getByRole('button',{name:'重新连接',exact:true}).waitFor({timeout:25000});check(await p.evaluate(()=>!!localStorage.getItem('credentials_cloud-yunda-d5gxrar1s14b2ee0d')),'云请求失败不会清除旧会话 '+mobile);await p.unroute(cloud,block);await p.getByRole('button',{name:'重新连接',exact:true}).click();await p.locator('.profile-heading').waitFor({timeout:30000});check((await p.locator('.profile-heading').innerText()).includes('持久登录验收同学'),'网络恢复后重试恢复真实账号 '+mobile);check(await p.getByRole('dialog',{name:'公告',exact:true}).count()===0,'恢复后仍记得公告已读 '+mobile);const other=await context.newPage();await other.goto(base+'#/me');await other.locator('.profile-heading').waitFor();check((await other.locator('.profile-heading').innerText()).includes('持久登录验收同学'),'新标签无需重登 '+mobile);await other.close();await p.getByRole('button',{name:'退出登录',exact:true}).click();await p.getByRole('heading',{name:'登录小食云记',exact:true}).waitFor();check(true,'退出真实账号成功 '+mobile)}catch(e){throw Error('After '+checks.at(-1)+': '+e.message)}finally{await context.close()}}
 return {base,checks,realSession:true,realWeChatDevice:false,passwordPrinted:false}
}
